:host {
  color-scheme: light dark;
  --active-color: light-dark(var(--color-gray-90), var(--color-gray-05));
  --active-background-color: light-dark(var(--color-gray-05), var(--color-gray-90));
  --container-border: none;
  --text: var(--active-color);
  --content-border: light-dark(var(--color-white), #4f5683);

  /* Close button colors */
  --close-button-background: var(--active-background-color);
  --close-button-background-active: var(--active-color);
  --close-button-background-hover: var(--close-button-background);
  --close-button-text: var(--text);
  --close-button-text-active: var(--active-background-color);
  --close-button-border: transparent;
  --close-button-border-hover: light-dark(#777580, var(--color-gray-05));
  --close-button-border-active: var(--active-color);
  --close-button-outline: currentColor;
